import json

wall_row = 3
test_cells = [(0,4), (1,0), (6,1)]
pattern = [(-1,-2), (-1,2), (0,-1), (0,1), (1,0)]

output = set()

for r, c in test_cells:
    dist = abs(r - wall_row)
    print(f"Cell ({r},{c}): dist={dist}")

    if dist == 2:
        pattern_list = pattern
        print("  → 5-cell pattern")
    elif dist >= 3:
        # 1 step toward wall
        if r < wall_row:
            dr, dc = 1, 0  # Move down toward wall
        else:
            dr, dc = -1, 0  # Move up toward wall
        pattern_list = [(dr, dc)]
        print("  → 1-out pattern")

    for dr, dc in pattern_list:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 12 and 0 <= nc < 8:
            if r < wall_row and nr < wall_row:
                output.add((nr, nc))
            elif r >= wall_row and nr > wall_row:
                output.add((nr, nc))

print(f"\nOutputs: {sorted(output)} (count={len(output)})")

grid = [[0 for _ in range(8)] for _ in range(12)]
for r, c in sorted(output):
    grid[r][c] = 4

grid_str = "\n".join(" ".join(str(x) for x in row) for row in grid)
print(json.dumps({"action": "submit", "grid": grid_str}))
